// Secrets are not part of wrangler.jsonc, so wrangler types cannot see them.
// These augmentations merge with the declarations generated by `wrangler types`:
// the global `Env` is used by worker code, `Cloudflare.Env` backs the `env`
// export from `cloudflare:workers`.
interface Env {
	JWT_SECRET: string;
}

declare namespace Cloudflare {
	interface Env {
		JWT_SECRET: string;
	}
}
